-- Starter class-wise curriculum for the Alyntis learning platform.
-- Safe to re-run: unique slugs prevent duplicate records.

ALTER TABLE courses ADD COLUMN IF NOT EXISTS class_level text;
CREATE INDEX IF NOT EXISTS idx_courses_class_level ON courses(class_level);

INSERT INTO courses (title, slug, description, class_level, status, sort_order)
VALUES
('Class 1 — Young Makers', 'class-1-young-makers', 'Explore making, simple mechanisms and creative problem solving through hands-on activities.', '1', 'available', 1),
('Class 2 — Exploring Machines', 'class-2-exploring-machines', 'Discover gears, motion and simple machines through guided builds.', '2', 'available', 2),
('Class 3 — Electronics Foundations', 'class-3-electronics-foundations', 'Learn circuits, LEDs, switches and the foundations of electronics.', '3', 'available', 3),
('Class 4 — Sensors & Smart Systems', 'class-4-sensors-smart-systems', 'Use sensors and simple control systems to make responsive devices.', '4', 'available', 4),
('Class 5 — Arduino Foundations', 'class-5-arduino-foundations', 'Combine coding and electronics with introductory Arduino projects.', '5', 'available', 5),
('Class 6 — Robotics & Automation', 'class-6-robotics-automation', 'Build sensor-driven robotic and automated systems.', '6', 'available', 6),
('Class 7 — IoT & Connected Devices', 'class-7-iot-connected-devices', 'Connect sensors and devices to the internet and visualize useful data.', '7', 'available', 7),
('Class 8 — Advanced Robotics', 'class-8-advanced-robotics', 'Develop autonomous robots using sensors, motors and control logic.', '8', 'available', 8),
('Class 9 — AI & Computer Vision', 'class-9-ai-computer-vision', 'Explore AI inference, datasets and computer vision applications.', '9', 'available', 9),
('Class 10 — AI, IoT & Smart Applications', 'class-10-ai-iot-smart-applications', 'Integrate AI, IoT and sensor systems into real-world prototypes.', '10', 'available', 10),
('Class 11 — Drones & Autonomous Systems', 'class-11-drones-autonomous-systems', 'Learn drone telemetry, navigation concepts and autonomous-system design.', '11', 'available', 11),
